-- IMPIX 기업 확장 DDL (ksxgen 생성물, 직접 수정 금지) — Core 스키마 ksx 참조
CREATE SCHEMA IF NOT EXISTS ext;

CREATE TABLE ext."StandardCost" ( -- 표준원가 (확장 명사)
    "StandardCostSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- 표준원가 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- 공장식별자
    "CreatorID" VARCHAR(50), -- 등록자식별자
    "CreationDateTime" TIMESTAMP, -- 등록일시
    "ModifierID" VARCHAR(50), -- 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- 수정일시
    "Note" VARCHAR(1000), -- 비고
    "StandardCostID" VARCHAR(50) NOT NULL, -- 표준원가식별자
    "ItemID" VARCHAR(50) NOT NULL, -- 품목식별자
    "OperationID" VARCHAR(50), -- 공정식별자
    "CostPeriodStartDate" DATE NOT NULL, -- 원가기간시작일
    "CostPeriodEndDate" DATE, -- 원가기간종료일
    "StandardCostAmount" NUMERIC(18,6) NOT NULL, -- 표준원가
    "MaterialCostAmount" NUMERIC(18,6), -- 재료비
    "LaborCostAmount" NUMERIC(18,6), -- 노무비
    "OverheadCostAmount" NUMERIC(18,6), -- 경비
    "CurrencyCode" VARCHAR(30), -- 환종코드
    "ItemUOMCode" VARCHAR(30), -- 기준단위코드
    CONSTRAINT "PK_StandardCost" PRIMARY KEY ("StandardCostSequenceNo"),
    CONSTRAINT "UK_StandardCost" UNIQUE ("EnterpriseID", "StandardCostID")
);
COMMENT ON TABLE ext."StandardCost" IS '표준원가 — 품목(필요 시 공정 단계)의 원가 기간별 표준원가와 원가 요소를 의미한다. 재공·불량·재고 금액 환산의 기준이 된다.';
COMMENT ON COLUMN ext."StandardCost"."StandardCostSequenceNo" IS '표준원가 일련번호';
COMMENT ON COLUMN ext."StandardCost"."EnterpriseID" IS '회사식별자';
COMMENT ON COLUMN ext."StandardCost"."SiteID" IS '사업장식별자';
COMMENT ON COLUMN ext."StandardCost"."PlantID" IS '공장식별자';
COMMENT ON COLUMN ext."StandardCost"."CreatorID" IS '등록자식별자';
COMMENT ON COLUMN ext."StandardCost"."CreationDateTime" IS '등록일시';
COMMENT ON COLUMN ext."StandardCost"."ModifierID" IS '수정자식별자';
COMMENT ON COLUMN ext."StandardCost"."ModificationDateTime" IS '수정일시';
COMMENT ON COLUMN ext."StandardCost"."Note" IS '비고';
COMMENT ON COLUMN ext."StandardCost"."StandardCostID" IS '표준원가식별자';
COMMENT ON COLUMN ext."StandardCost"."ItemID" IS '품목식별자';
COMMENT ON COLUMN ext."StandardCost"."OperationID" IS '공정식별자';
COMMENT ON COLUMN ext."StandardCost"."CostPeriodStartDate" IS '원가기간시작일';
COMMENT ON COLUMN ext."StandardCost"."CostPeriodEndDate" IS '원가기간종료일';
COMMENT ON COLUMN ext."StandardCost"."StandardCostAmount" IS '표준원가';
COMMENT ON COLUMN ext."StandardCost"."MaterialCostAmount" IS '재료비';
COMMENT ON COLUMN ext."StandardCost"."LaborCostAmount" IS '노무비';
COMMENT ON COLUMN ext."StandardCost"."OverheadCostAmount" IS '경비';
COMMENT ON COLUMN ext."StandardCost"."CurrencyCode" IS '환종코드';
COMMENT ON COLUMN ext."StandardCost"."ItemUOMCode" IS '기준단위코드';

CREATE TABLE ext."CustomerComplaint" ( -- 고객클레임 (확장 명사)
    "CustomerComplaintSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- 고객클레임 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- 공장식별자
    "CreatorID" VARCHAR(50), -- 등록자식별자
    "CreationDateTime" TIMESTAMP, -- 등록일시
    "ModifierID" VARCHAR(50), -- 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- 수정일시
    "Note" VARCHAR(1000), -- 비고
    "CustomerComplaintID" VARCHAR(50) NOT NULL, -- 고객클레임식별자
    "CustomerID" VARCHAR(50) NOT NULL, -- 고객사식별자
    "ItemID" VARCHAR(50), -- 품목식별자
    "LotID" VARCHAR(50), -- 로트식별자
    "CustomerComplaintType" VARCHAR(30) NOT NULL, -- 고객클레임유형
    "OccurrenceDate" DATE, -- 발생일
    "ComplaintReceiptDate" DATE, -- 접수일
    "DefectTypeCode" VARCHAR(30), -- 불량유형코드
    "DefectTypeDetailCode" VARCHAR(30), -- 불량유형상세코드
    "ComplaintQuantity" NUMERIC(18,6), -- 클레임수량
    "ItemUOMCode" VARCHAR(30), -- 기준단위코드
    "ResponseDueDate" DATE NOT NULL, -- 대책회신기한
    "ResponseDate" DATE, -- 대책회신일
    "CloseDate" DATE, -- 종결일
    "CustomerComplaintStatusCode" VARCHAR(30), -- 고객클레임상태코드
    "ComplaintAmount" NUMERIC(18,6), -- 클레임금액
    "CurrencyCode" VARCHAR(30), -- 환종코드
    "CauseOperationID" VARCHAR(50), -- 원인공정식별자
    "ComplaintDescription" VARCHAR(255), -- 클레임내용
    CONSTRAINT "PK_CustomerComplaint" PRIMARY KEY ("CustomerComplaintSequenceNo"),
    CONSTRAINT "UK_CustomerComplaint" UNIQUE ("EnterpriseID", "CustomerComplaintID")
);
COMMENT ON TABLE ext."CustomerComplaint" IS '고객클레임 — 고객이 제기한 제품 부적합(입고검사 부적합·라인 중단·필드 반송)과 대책 회신·종결 이력을 의미한다.';
COMMENT ON COLUMN ext."CustomerComplaint"."CustomerComplaintSequenceNo" IS '고객클레임 일련번호';
COMMENT ON COLUMN ext."CustomerComplaint"."EnterpriseID" IS '회사식별자';
COMMENT ON COLUMN ext."CustomerComplaint"."SiteID" IS '사업장식별자';
COMMENT ON COLUMN ext."CustomerComplaint"."PlantID" IS '공장식별자';
COMMENT ON COLUMN ext."CustomerComplaint"."CreatorID" IS '등록자식별자';
COMMENT ON COLUMN ext."CustomerComplaint"."CreationDateTime" IS '등록일시';
COMMENT ON COLUMN ext."CustomerComplaint"."ModifierID" IS '수정자식별자';
COMMENT ON COLUMN ext."CustomerComplaint"."ModificationDateTime" IS '수정일시';
COMMENT ON COLUMN ext."CustomerComplaint"."Note" IS '비고';
COMMENT ON COLUMN ext."CustomerComplaint"."CustomerComplaintID" IS '고객클레임식별자';
COMMENT ON COLUMN ext."CustomerComplaint"."CustomerID" IS '고객사식별자';
COMMENT ON COLUMN ext."CustomerComplaint"."ItemID" IS '품목식별자';
COMMENT ON COLUMN ext."CustomerComplaint"."LotID" IS '로트식별자';
COMMENT ON COLUMN ext."CustomerComplaint"."CustomerComplaintType" IS '고객클레임유형';
COMMENT ON COLUMN ext."CustomerComplaint"."OccurrenceDate" IS '발생일';
COMMENT ON COLUMN ext."CustomerComplaint"."ComplaintReceiptDate" IS '접수일';
COMMENT ON COLUMN ext."CustomerComplaint"."DefectTypeCode" IS '불량유형코드';
COMMENT ON COLUMN ext."CustomerComplaint"."DefectTypeDetailCode" IS '불량유형상세코드';
COMMENT ON COLUMN ext."CustomerComplaint"."ComplaintQuantity" IS '클레임수량';
COMMENT ON COLUMN ext."CustomerComplaint"."ItemUOMCode" IS '기준단위코드';
COMMENT ON COLUMN ext."CustomerComplaint"."ResponseDueDate" IS '대책회신기한';
COMMENT ON COLUMN ext."CustomerComplaint"."ResponseDate" IS '대책회신일';
COMMENT ON COLUMN ext."CustomerComplaint"."CloseDate" IS '종결일';
COMMENT ON COLUMN ext."CustomerComplaint"."CustomerComplaintStatusCode" IS '고객클레임상태코드';
COMMENT ON COLUMN ext."CustomerComplaint"."ComplaintAmount" IS '클레임금액';
COMMENT ON COLUMN ext."CustomerComplaint"."CurrencyCode" IS '환종코드';
COMMENT ON COLUMN ext."CustomerComplaint"."CauseOperationID" IS '원인공정식별자';
COMMENT ON COLUMN ext."CustomerComplaint"."ComplaintDescription" IS '클레임내용';

CREATE TABLE ext."QualityCost" ( -- 품질비용 (확장 명사)
    "QualityCostSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- 품질비용 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- 공장식별자
    "CreatorID" VARCHAR(50), -- 등록자식별자
    "CreationDateTime" TIMESTAMP, -- 등록일시
    "ModifierID" VARCHAR(50), -- 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- 수정일시
    "Note" VARCHAR(1000), -- 비고
    "QualityCostID" VARCHAR(50) NOT NULL, -- 품질비용식별자
    "CostPeriodStartDate" DATE NOT NULL, -- 원가기간시작일
    "CostPeriodEndDate" DATE, -- 원가기간종료일
    "QualityCostClass" VARCHAR(30) NOT NULL, -- 품질비용구분
    "QualityCostItem" VARCHAR(30) NOT NULL, -- 품질비용항목
    "QualityCostAmount" NUMERIC(18,6) NOT NULL, -- 품질비용금액
    "CurrencyCode" VARCHAR(30), -- 환종코드
    "SourceDocumentReference" VARCHAR(255), -- 근거문서
    CONSTRAINT "PK_QualityCost" PRIMARY KEY ("QualityCostSequenceNo"),
    CONSTRAINT "UK_QualityCost" UNIQUE ("EnterpriseID", "QualityCostID")
);
COMMENT ON TABLE ext."QualityCost" IS '품질비용 — 원가 기간별 품질비용(Q-COST)을 예방·평가·내부실패·외부실패 구분과 비용 항목으로 집계한 값을 의미한다.';
COMMENT ON COLUMN ext."QualityCost"."QualityCostSequenceNo" IS '품질비용 일련번호';
COMMENT ON COLUMN ext."QualityCost"."EnterpriseID" IS '회사식별자';
COMMENT ON COLUMN ext."QualityCost"."SiteID" IS '사업장식별자';
COMMENT ON COLUMN ext."QualityCost"."PlantID" IS '공장식별자';
COMMENT ON COLUMN ext."QualityCost"."CreatorID" IS '등록자식별자';
COMMENT ON COLUMN ext."QualityCost"."CreationDateTime" IS '등록일시';
COMMENT ON COLUMN ext."QualityCost"."ModifierID" IS '수정자식별자';
COMMENT ON COLUMN ext."QualityCost"."ModificationDateTime" IS '수정일시';
COMMENT ON COLUMN ext."QualityCost"."Note" IS '비고';
COMMENT ON COLUMN ext."QualityCost"."QualityCostID" IS '품질비용식별자';
COMMENT ON COLUMN ext."QualityCost"."CostPeriodStartDate" IS '원가기간시작일';
COMMENT ON COLUMN ext."QualityCost"."CostPeriodEndDate" IS '원가기간종료일';
COMMENT ON COLUMN ext."QualityCost"."QualityCostClass" IS '품질비용구분';
COMMENT ON COLUMN ext."QualityCost"."QualityCostItem" IS '품질비용항목';
COMMENT ON COLUMN ext."QualityCost"."QualityCostAmount" IS '품질비용금액';
COMMENT ON COLUMN ext."QualityCost"."CurrencyCode" IS '환종코드';
COMMENT ON COLUMN ext."QualityCost"."SourceDocumentReference" IS '근거문서';

CREATE TABLE ext."InventorySnapshot" ( -- 일별재고 (확장 명사)
    "InventorySnapshotSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- 일별재고 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- 공장식별자
    "CreatorID" VARCHAR(50), -- 등록자식별자
    "CreationDateTime" TIMESTAMP, -- 등록일시
    "ModifierID" VARCHAR(50), -- 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- 수정일시
    "Note" VARCHAR(1000), -- 비고
    "InventorySnapshotDate" DATE NOT NULL, -- 재고기준일
    "WarehouseID" VARCHAR(50) NOT NULL, -- 창고식별자
    "ItemID" VARCHAR(50) NOT NULL, -- 품목식별자
    "InventoryQuantity" NUMERIC(18,6), -- 현재고수량
    "ItemUOMCode" VARCHAR(30), -- 기준단위코드
    CONSTRAINT "PK_InventorySnapshot" PRIMARY KEY ("InventorySnapshotSequenceNo"),
    CONSTRAINT "UK_InventorySnapshot" UNIQUE ("EnterpriseID", "InventorySnapshotDate", "WarehouseID", "ItemID")
);
COMMENT ON TABLE ext."InventorySnapshot" IS '일별재고 — 기준일 마감 시점의 창고·품목별 재고수량을 의미한다. 표준 재고(Inventory)는 현재고만 정의하므로 기준일 이력을 별도로 둔다.';
COMMENT ON COLUMN ext."InventorySnapshot"."InventorySnapshotSequenceNo" IS '일별재고 일련번호';
COMMENT ON COLUMN ext."InventorySnapshot"."EnterpriseID" IS '회사식별자';
COMMENT ON COLUMN ext."InventorySnapshot"."SiteID" IS '사업장식별자';
COMMENT ON COLUMN ext."InventorySnapshot"."PlantID" IS '공장식별자';
COMMENT ON COLUMN ext."InventorySnapshot"."CreatorID" IS '등록자식별자';
COMMENT ON COLUMN ext."InventorySnapshot"."CreationDateTime" IS '등록일시';
COMMENT ON COLUMN ext."InventorySnapshot"."ModifierID" IS '수정자식별자';
COMMENT ON COLUMN ext."InventorySnapshot"."ModificationDateTime" IS '수정일시';
COMMENT ON COLUMN ext."InventorySnapshot"."Note" IS '비고';
COMMENT ON COLUMN ext."InventorySnapshot"."InventorySnapshotDate" IS '재고기준일';
COMMENT ON COLUMN ext."InventorySnapshot"."WarehouseID" IS '창고식별자';
COMMENT ON COLUMN ext."InventorySnapshot"."ItemID" IS '품목식별자';
COMMENT ON COLUMN ext."InventorySnapshot"."InventoryQuantity" IS '현재고수량';
COMMENT ON COLUMN ext."InventorySnapshot"."ItemUOMCode" IS '기준단위코드';

CREATE TABLE ext."LotInventory" ( -- 로트별재고 (확장 명사)
    "LotInventorySequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- 로트별재고 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- 공장식별자
    "CreatorID" VARCHAR(50), -- 등록자식별자
    "CreationDateTime" TIMESTAMP, -- 등록일시
    "ModifierID" VARCHAR(50), -- 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- 수정일시
    "Note" VARCHAR(1000), -- 비고
    "WarehouseID" VARCHAR(50) NOT NULL, -- 창고식별자
    "ItemID" VARCHAR(50) NOT NULL, -- 품목식별자
    "LotID" VARCHAR(50) NOT NULL, -- 로트식별자
    "GoodsReceiptDate" DATE NOT NULL, -- 입고처리일
    "InventoryQuantity" NUMERIC(18,6), -- 현재고수량
    "ItemUOMCode" VARCHAR(30), -- 기준단위코드
    CONSTRAINT "PK_LotInventory" PRIMARY KEY ("LotInventorySequenceNo"),
    CONSTRAINT "UK_LotInventory" UNIQUE ("EnterpriseID", "WarehouseID", "ItemID", "LotID")
);
COMMENT ON TABLE ext."LotInventory" IS '로트별재고 — 창고·품목의 현재고를 로트와 입고일 단위로 나눈 재고를 의미한다. 재고 경과일(장기 체화)·선입선출 판단의 근거가 된다.';
COMMENT ON COLUMN ext."LotInventory"."LotInventorySequenceNo" IS '로트별재고 일련번호';
COMMENT ON COLUMN ext."LotInventory"."EnterpriseID" IS '회사식별자';
COMMENT ON COLUMN ext."LotInventory"."SiteID" IS '사업장식별자';
COMMENT ON COLUMN ext."LotInventory"."PlantID" IS '공장식별자';
COMMENT ON COLUMN ext."LotInventory"."CreatorID" IS '등록자식별자';
COMMENT ON COLUMN ext."LotInventory"."CreationDateTime" IS '등록일시';
COMMENT ON COLUMN ext."LotInventory"."ModifierID" IS '수정자식별자';
COMMENT ON COLUMN ext."LotInventory"."ModificationDateTime" IS '수정일시';
COMMENT ON COLUMN ext."LotInventory"."Note" IS '비고';
COMMENT ON COLUMN ext."LotInventory"."WarehouseID" IS '창고식별자';
COMMENT ON COLUMN ext."LotInventory"."ItemID" IS '품목식별자';
COMMENT ON COLUMN ext."LotInventory"."LotID" IS '로트식별자';
COMMENT ON COLUMN ext."LotInventory"."GoodsReceiptDate" IS '입고처리일';
COMMENT ON COLUMN ext."LotInventory"."InventoryQuantity" IS '현재고수량';
COMMENT ON COLUMN ext."LotInventory"."ItemUOMCode" IS '기준단위코드';

CREATE TABLE ext."SalesPlanExt" ( -- 판매계획 확장 (확장 속성 → SalesPlan)
    "SalesPlanExtSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- 판매계획 확장 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- 회사식별자
    "SalesPlanID" VARCHAR(50) NOT NULL, -- 판매계획식별자
    "SalesPlanType" VARCHAR(30) NOT NULL, -- 판매계획유형
    "CustomerID" VARCHAR(50), -- 고객사식별자
    "SalesPlanVersion" INTEGER, -- 판매계획버전
    CONSTRAINT "PK_SalesPlanExt" PRIMARY KEY ("SalesPlanExtSequenceNo"),
    CONSTRAINT "UK_SalesPlanExt" UNIQUE ("EnterpriseID", "SalesPlanID")
);
COMMENT ON TABLE ext."SalesPlanExt" IS '판매계획 확장 — 판매계획(SalesPlan)에 계획 유형(수요예측·판매계획)·고객·버전을 더한다.';
COMMENT ON COLUMN ext."SalesPlanExt"."SalesPlanExtSequenceNo" IS '판매계획 확장 일련번호';
COMMENT ON COLUMN ext."SalesPlanExt"."EnterpriseID" IS '회사식별자';
COMMENT ON COLUMN ext."SalesPlanExt"."SalesPlanID" IS '판매계획식별자';
COMMENT ON COLUMN ext."SalesPlanExt"."SalesPlanType" IS '판매계획유형';
COMMENT ON COLUMN ext."SalesPlanExt"."CustomerID" IS '고객사식별자';
COMMENT ON COLUMN ext."SalesPlanExt"."SalesPlanVersion" IS '판매계획버전';

CREATE TABLE ext."SalesOrderLineExt" ( -- 수주오더라인 확장 (확장 속성 → SalesOrderLine)
    "SalesOrderLineExtSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- 수주오더라인 확장 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- 회사식별자
    "SalesDocumentNumber" VARCHAR(50) NOT NULL, -- 수주문서번호
    "SalesDocumentSequence" INTEGER NOT NULL, -- 수주문서순번
    "UnitPrice" NUMERIC(18,6), -- 단가
    "CurrencyCode" VARCHAR(30), -- 환종코드
    "SalesAmount" NUMERIC(18,6), -- 판매금액
    CONSTRAINT "PK_SalesOrderLineExt" PRIMARY KEY ("SalesOrderLineExtSequenceNo"),
    CONSTRAINT "UK_SalesOrderLineExt" UNIQUE ("EnterpriseID", "SalesDocumentNumber", "SalesDocumentSequence")
);
COMMENT ON TABLE ext."SalesOrderLineExt" IS '수주오더라인 확장 — 수주오더라인에 판매단가·통화·판매금액을 더한다(매출액·Q-COST 매출 대비 비율).';
COMMENT ON COLUMN ext."SalesOrderLineExt"."SalesOrderLineExtSequenceNo" IS '수주오더라인 확장 일련번호';
COMMENT ON COLUMN ext."SalesOrderLineExt"."EnterpriseID" IS '회사식별자';
COMMENT ON COLUMN ext."SalesOrderLineExt"."SalesDocumentNumber" IS '수주문서번호';
COMMENT ON COLUMN ext."SalesOrderLineExt"."SalesDocumentSequence" IS '수주문서순번';
COMMENT ON COLUMN ext."SalesOrderLineExt"."UnitPrice" IS '단가';
COMMENT ON COLUMN ext."SalesOrderLineExt"."CurrencyCode" IS '환종코드';
COMMENT ON COLUMN ext."SalesOrderLineExt"."SalesAmount" IS '판매금액';

CREATE TABLE ext."AvailableInventoryExt" ( -- 가용재고 확장 (확장 속성 → AvailableInventory)
