CREATE TABLE ext."EquipmentParameterExt" ( -- 설비파라미터 확장 (확장 속성 → EquipmentParameter)
    "EquipmentParameterExtSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- 설비파라미터 확장 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- 회사식별자
    "ParameterID" VARCHAR(50) NOT NULL, -- 파라미터식별자
    "LCL" NUMERIC(18,6), -- 관리하한
    "UCL" NUMERIC(18,6), -- 관리상한
    CONSTRAINT "PK_EquipmentParameterExt" PRIMARY KEY ("EquipmentParameterExtSequenceNo"),
    CONSTRAINT "UK_EquipmentParameterExt" UNIQUE ("EnterpriseID", "ParameterID")
);
COMMENT ON TABLE ext."EquipmentParameterExt" IS '설비파라미터 확장 — 설비파라미터에 관리한계(LCL·UCL)를 더한다(규격한계 LSL·USL과 구분).';
COMMENT ON COLUMN ext."EquipmentParameterExt"."EquipmentParameterExtSequenceNo" IS '설비파라미터 확장 일련번호';
COMMENT ON COLUMN ext."EquipmentParameterExt"."EnterpriseID" IS '회사식별자';
COMMENT ON COLUMN ext."EquipmentParameterExt"."ParameterID" IS '파라미터식별자';
COMMENT ON COLUMN ext."EquipmentParameterExt"."LCL" IS '관리하한';
COMMENT ON COLUMN ext."EquipmentParameterExt"."UCL" IS '관리상한';

